    async def create_forwarding(
        self,
        *,
        mailbox_id: str | None = None,
        email: str | None = None,
    ) -> Forwarding:
        """
        Create a forwarding rule for a mailbox.

        All incoming emails to the mailbox will be redirected to the specified
        destination email address.
        A mailbox can have up to 5 forwarding rules. Forwarding to the mailbox's own
        email address is not allowed.

        Args:
            mailbox_id: ID of the mailbox for which to create the forwarding rule. (UUID
                format)
            email: Destination email address to which incoming emails will be forwarded.
                Must not be the same as the mailbox's own email address.
        """
        data = await self._client.request_json(
            "POST",
            "/mailbox/v1alpha1/forwardings",
            body={"mailbox_id": mailbox_id, "email": email},
        )
        return Forwarding.model_validate(data)

